-- 확인용 (실행 후):
SELECT
  (SELECT count(*) FROM yt_channel_videos WHERE group_ko='하이라이트' AND content_flag IS NULL) AS hl_visible,   -- 1911 → 1520 (재배정 31 + 보류 360 빠짐)
  (SELECT count(*) FROM yt_channel_videos WHERE '하이라이트'=ANY(with_groups)) AS hl_with;                         -- 13 → 11
